  ui_story_31650601_12_dialog_content = "\"¿Estigia?\" \"¡Estigia!\"",
  ui_story_31650601_13_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31650601_14_dialog_content = "Solo soy yo ahora... ¡Achu!",
  ui_story_31650601_15_dialog_content = "La temperatura bajo tierra congelada y mis límites suman a la conclusión...",
  ui_story_31650601_16_dialog_content = "No aguantaré mucho tiempo.",
