  ui_story_31650601_54_dialog_content = "La señal se cortó de nuevo...",
  ui_story_31650601_55_dialog_content = "Basándonos en todas las variables, la probabilidad de una operación de rescate exitosa es...",
  ui_story_31650601_56_option_content = "¡Detente!",
  ui_story_31650601_57_dialog_content = "¡Deja de calcular las probabilidades! Incluso si solo hay un uno por ciento de posibilidades, te sacaremos de ahí al cien por ciento.",
