  ui_story_31650601_61_dialog_content = "¿Lo harías por mí...?",
  ui_story_31650601_62_dialog_content = "O tal vez estoy delirando por el frío...",
  ui_story_31650601_63_dialog_content = "Esa voz en el comunicador...",
  ui_story_31650601_64_dialog_content = "¿Qué miembro del equipo era?",
  ui_story_31650601_65_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_31650601_66_dialog_content = "<size=45><color=#e8d9bb>¡¡¡Boom!!!</color></size>",
  ui_story_31650601_67_dialog_content = "Ciel!",
  ui_story_31650601_68_dialog_content = "Estoy... aquí...",
  ui_story_31650601_69_dialog_content = "¡Por fin te encontré!",
  ui_story_31650601_70_dialog_content = "O-Oficial Gronru? ¿Qué está haciendo aquí en persona...",
  ui_story_31650601_71_dialog_content = "Estaba en soporte técnico en una Subciudad cercana cuando escuché que había un accidente, así que me apresuré a venir.",
  ui_story_31650601_72_dialog_content = "Me asustaste muchísimo. Pensé que mi pequeña Ciel se había sacrificado en el campo helado por Illumina...",
  ui_story_31650601_73_dialog_content = "Lamento la espera. Ha estado cayendo una ventisca, así que pasamos mucho tiempo en condiciones terribles abriendo camino.",
  ui_story_31650601_74_dialog_content = "Afortunadamente, el sol finalmente salió hoy y ¡podemos continuar! No estarás congelado de la mente, ¿verdad?",
  ui_story_31650601_75_dialog_content = "Gracias, oficial Gronru, pero estoy bien.",
  ui_story_31650601_76_dialog_content = "Todos nos sentimos aliviados de verte bien, ¡Jefe!",
  ui_story_31650601_77_dialog_content = "Ustedes... En realidad, aguanté gracias a sus ánimos a través de la comunicación.",
  ui_story_31650601_78_dialog_content = "Me gustaría decirles a todos... ¡Gracias! Y también... ¡Perdón!",
  ui_story_31650601_79_dialog_content = "No solo no hice mi trabajo como jefe, sino que también tuviste que venir a salvarme...",
  ui_story_31650601_80_dialog_content = "¡No digas eso! El jefe Ciel es el técnico más tranquilo y profesional que hemos conocido, ¡y confiamos plenamente en ti!",
  ui_story_31650601_81_dialog_content = "¡Sin mencionar que si no fuera por ti, podríamos estar todos enterrados ahí!",
  ui_story_31650601_82_dialog_content = "Sin embargo, nunca pudimos contactarte en el comunicador...",
  ui_story_31650601_83_dialog_content = "¿Qué? Entonces, ¿quién me estaba animando...?",
  ui_story_31650601_84_dialog_content = "Bueno, parece que PlayerName ha estado trabajando detrás de escena otra vez.",
  ui_story_31650601_85_dialog_content = "Por cómo lo dices, parece que hice algo malo.",
  ui_story_31650601_86_dialog_content = "¿PlayerName también está aquí?!",
  ui_story_31650601_87_dialog_content = "Fue una emergencia, así que tuve que pedirle a PlayerName que me llevara en el Colossus para el rescate.",
  ui_story_31650601_88_dialog_content = "Entonces es PlayerName quien me ha estado tranquilizando todo este tiempo...",
  ui_story_31650601_89_dialog_content = "¡Me da vergüenza que hayas visto lo asustado que estaba!",
  ui_story_31650601_90_option_content = "¡No deberías estar!",
  ui_story_31650601_91_dialog_content = "¡Sacrificarte por la seguridad de los demás nunca es motivo de vergüenza!",
  ui_story_31650601_92_dialog_content = "Y pensé que era adorable la forma en que hablabas contigo mismo cuando estabas atrapado.",
  ui_story_31650601_93_option_content = "¡Está bien!",
  ui_story_31650601_94_dialog_content = "Es natural hablar contigo mismo cuando estás atrapado solo bajo tierra.",
  ui_story_31650601_95_dialog_content = "Ni siquiera quiero imaginar qué habría hecho en aquel entonces sin Soroz para acompañarme.",
  ui_story_31650601_96_dialog_content = "Espera, ¿escuchaste todas esas cosas que estaba murmurando para mí mismo?!",
  ui_story_31650601_97_dialog_content = "Él tiene poderes psíquicos, Ciel. No lo olvides.",
  ui_story_31650601_98_dialog_content = "Incluso con las habilidades psíquicas, probablemente no podría localizar la posición de Ciel a través del hielo espeso si ella no estuviera murmurando.",
  ui_story_31650601_99_dialog_content = "Entonces eso significa que tú también lo escuchaste, PlayerName...",
  ui_story_31650601_100_dialog_content = "¿Qué? ¿Dijiste algo que no querías que PlayerName escuchara, Ciel?",
  ui_story_31650601_101_dialog_content = "¡No, no lo hice! Gracias por tu esfuerzo en salvarme, oficial Gronru, PlayerName!",
  ui_story_31650601_102_dialog_content = "¡Ahora debo poner al equipo de nuevo en marcha con el proyecto!",
  ui_story_31650601_103_dialog_content = "Tómatelo con calma, Ciel, ¡acabas de salir con vida!",
  ui_story_31650601_104_dialog_content = "¿Qué le pasa? Corriendo tan rápido...",
